import * as yup from "yup";

const schema = yup.object().shape({
  name: yup.string().required(),
  age: yup.number().min(0).max(120).required()
});

const result = await schema.validate({ name: "Alice", age: 30 });

import * as Yup from "yup";

const SignupSchema = Yup.object({
  email: Yup.string().email("Invalid email").required("Required"),
  password: Yup.string()
    .min(8, "Too short")
    .matches(/[0-9]/, "Needs a number")
    .required("Required"),
  age: Yup.number().positive().integer().max(120),
});

await SignupSchema.validate(
  { email: "ada@example.com", password: "secret1" },
  { abortEarly: false },
); // rejects with a ValidationError

const isValid = SignupSchema.isValidSync({ email: "x" });

const AddressSchema = Yup.object({
  country: Yup.string().required(),
  postalCode: Yup.string().when("country", {
    is: "US",
    then: (schema) =>
      schema.matches(/^\d{5}$/, "Five-digit ZIP required").required(),
    otherwise: (schema) => schema.optional(),
  }),
});
